import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as n,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const E=JSON.parse('{"title":"AIOps 通用 Agent 探索","description":"把 Cursor 局限在单机的 AI 提效云端化：Prompt + Eino ReAct 引擎 + Docker 沙箱 + YAML Agent 定义，用提示词定义 DevOps 流程。","frontmatter":{"title":"AIOps 通用 Agent 探索","description":"把 Cursor 局限在单机的 AI 提效云端化：Prompt + Eino ReAct 引擎 + Docker 沙箱 + YAML Agent 定义，用提示词定义 DevOps 流程。","domain":"tech","tags":["tech","case","aiops","agent","devops"],"navOrder":78,"topicId":"cases-aiops-agent-exploration","layer":"appendix","status":"case","nodeType":"evidence","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/cases/aiops-agent-exploration.md","filePath":"zh/tech/appendices/cases/aiops-agent-exploration.md","lastUpdated":1791123418000}'),i={name:"zh/tech/appendices/cases/aiops-agent-exploration.md"};function p(o,s,l,r,h,d){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="aiops-通用-agent-探索" tabindex="-1">AIOps 通用 Agent 探索 <a class="header-anchor" href="#aiops-通用-agent-探索" aria-label="Permalink to &quot;AIOps 通用 Agent 探索&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://tech.qimao.com/aiops-tong-yong-agent-tan-suo-simple/" target="_blank" rel="noreferrer">AIOps 通用 Agent 探索（Simple）</a> - @秦皓</p></blockquote><h2 id="背景与理念" tabindex="-1">背景与理念 <a class="header-anchor" href="#背景与理念" aria-label="Permalink to &quot;背景与理念&quot;">​</a></h2><p>Cursor 等 IDE 内 AI 贯穿了需求分析、文档、评审、部署调试、日志分析，但<strong>局限在单机</strong>、无法与现有系统集成；为每个场景开发独立 Agent 又耗费人力。</p><p>核心理念：践行 Manus 提倡的 <strong>&quot;Less structure, more intelligence&quot;（更少结构，更多智能）</strong>——通过 <strong>Prompt + LLM（Agent）+ Tools + Workspace</strong> 落地 DevOps 流程：让用户通过提示词定义具体流程，即可快速实现该流程的 AI 自动化集成。</p><p>理论基础是 <a href="https://arxiv.org/pdf/2210.03629" target="_blank" rel="noreferrer">ReAct 框架</a>（Reasoning → Action → Observation 循环）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while not task_finished:</span></span>
<span class="line"><span>    thought = model.reason(context)</span></span>
<span class="line"><span>    action = model.act(thought)</span></span>
<span class="line"><span>    observation = environment.execute(action)</span></span>
<span class="line"><span>    context.update(observation)</span></span></code></pre></div><p>主线展开见 <a href="/zh/tech/06-agent-systems/agent-runtime.html">Agent 运行时</a>；本页保留场景化落地证据。</p><h2 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 管理平台（规划中）：任务管理 / 对外 API / 周期 Job / 报告 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ AIOps 通用 Agent                             │</span></span>
<span class="line"><span>│  - ReAct 引擎（基于字节开源的 Eino 框架，核心约百行） │</span></span>
<span class="line"><span>│  - Tools（如 bash_command 一个工具即可起步）        │</span></span>
<span class="line"><span>│  - 运行环境（Docker 容器隔离）                    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Langfuse 调用监控 · Bashly 封装依赖工具           │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre></div><p>四个核心组件：</p><ul><li><strong>Prompt</strong>：核心工作是写提示词（定义流程）</li><li><strong>LLM（ReAct Engine）</strong>：Eino ReAct Agent + 系统提示词 + 工具列表 + 执行环境</li><li><strong>Tools</strong>：MR 报告场景只需一个 <code>bash_command</code> 工具（params: command 必填，working_dir / timeout / environment 可选）；运行时依赖（codeup、git、jq）由 Docker 镜像提供</li><li><strong>Workspace</strong>：独立 Docker 容器隔离（内存 512MB、CPU 1.0、超时 30min），代码与数据卷挂载</li></ul><h2 id="agent-定义-yaml" tabindex="-1">Agent 定义（YAML） <a class="header-anchor" href="#agent-定义-yaml" aria-label="Permalink to &quot;Agent 定义（YAML）&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;code_review&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Code Review&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  system_prompt_doc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;task_cr.md&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 从文件加载系统提示词</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  user_prompt_template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;请为我给 repo_id=\${{repo_id}}, local_id=\${{local_id}} 的合并请求进行代码评审&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;codebase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/var/aiops/repos/\${{repo_id}}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/workspace/src&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  post_shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;codeup mr comment add ... &#39;AI 代码评审报告: \${{report_url}}&#39;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  report_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aiops/mr/reports/\${{repo_id}}/\${{local_id}}/&quot;</span></span></code></pre></div><h2 id="场景实践-mr-报告总结" tabindex="-1">场景实践：MR 报告总结 <a class="header-anchor" href="#场景实践-mr-报告总结" aria-label="Permalink to &quot;场景实践：MR 报告总结&quot;">​</a></h2><p>提示词定义四步流程：收集 MR 信息（<code>codeup mr get</code>）→ 理解变更上下文（<code>codeup mr tree</code> + repo file）→ 分析变更 → 追加评审描述（<code>codeup mr update</code>）。</p><p><strong>关键设计——Common Commands 模板</strong>：在提示词中嵌入常用命令的返回格式示例，让 AI 知道如何解析命令输出。输出为结构化评审报告：评估结论（建议合并 / 修复后合并 / 不建议）→ 评审流程总结 → 关键建议（必须修复 / 质量建议 / 测试覆盖建议）。</p><h2 id="核心价值与展望" tabindex="-1">核心价值与展望 <a class="header-anchor" href="#核心价值与展望" aria-label="Permalink to &quot;核心价值与展望&quot;">​</a></h2><table tabindex="0"><thead><tr><th>价值点</th><th>说明</th></tr></thead><tbody><tr><td>简单高效</td><td>Markdown 提示词定义业务流程即可获得该场景的 Agent 能力</td></tr><tr><td>隐私安全</td><td>自研自托管，代码与数据不出域</td></tr><tr><td>易于集成</td><td>标准 Open API，第三方系统快速接入</td></tr><tr><td>异步处理</td><td>API 集成或定时 Job</td></tr><tr><td>集中管理</td><td>脱离单机 IDE 云端化，一人开发全员受益</td></tr></tbody></table><p>未来方向：管理平台（Web UI 统一管理提示词/工具/报告）、多 Agent 协同与记忆管理、迁移到业务通用 Agent。</p>`,20)])])}const m=a(i,[["render",p]]);export{E as __pageData,m as default};
